function derivationStore(
	input: Readonly<{
		issued: ReadonlyMap<number, DurableIssueCommit>;
		lineage: DurableLineage;
		rows: readonly DurableIssuanceOutboxRecord[];
	}>
): DurableIssuanceStore {
	return Object.freeze({
