	captureCloseGraph():
		| Readonly<{
				readonly charges: ReadonlyMap<string, number>;
				readonly frontier: readonly string[];
				readonly vertices: ReadonlyMap<string, EpochVertex>;
		  }>
		| undefined;
	stageSnapshot(): Promise<
		Readonly<
