+		const issued = await input.issuanceStore.readIssued(input.issuanceScope, expected);
+		if (!exactIssuancePair(row, issued, input.issuanceScope, expected)) {
+			throw new TypeError(CREATOR_ISSUANCE_RETIREMENT_UNAVAILABLE);
+		}
